test('createInvoice applies tier discount when discountPercent not provided', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  // C-003 is 'Kite & Co' with 'silver' tier = 2.5% discount
  assert.equal(r.value.lines[0].discountPercent, 2.5);
});

test('createInvoice applies gold tier discount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  // C-001 should have gold tier = 5% discount
  assert.equal(r.value.lines[0].discountPercent, 5);
});

test('createInvoice applies standard tier discount', () => {
  const r = createInvoice({
    customerId: 'C-004',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  // C-004 should have standard tier = 0% discount
  assert.equal(r.value.lines[0].discountPercent, 0);
});

test('createInvoice explicit discountPercent 0 overrides tier discount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }],
  });
  assert.equal(r.ok, true);
  // Explicitly set to 0, should not use tier discount
  assert.equal(r.value.lines[0].discountPercent, 0);
});

test('createInvoice explicit discount overrides tier discount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 10 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 10);
});

test('createInvoice applies tier discount to all lines without explicit discount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3, discountPercent: 15 },
      { sku: 'COPY-HOUR', qty: 2 },
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 5); // tier discount
  assert.equal(r.value.lines[1].discountPercent, 15); // explicit
  assert.equal(r.value.lines[2].discountPercent, 5); // tier discount
});

test('addLine applies tier discount when discountPercent not provided', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(invoice.ok, true);

  const r = addLine(invoice.value, { sku: 'DEV-HOUR', qty: 3 });
  assert.equal(r.ok, true);
  // C-001 is gold tier = 5% discount
  assert.equal(r.value.lines[1].discountPercent, 5);
});

test('addLine explicit discountPercent 0 overrides tier discount', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(invoice.ok, true);

  const r = addLine(invoice.value, { sku: 'DEV-HOUR', qty: 3, discountPercent: 0 });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[1].discountPercent, 0);
});

test('tier discount affects invoice totals', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 100 }],
  });
  assert.equal(invoice.ok, true);
  const r = invoiceTotals(invoice.value);
  assert.equal(r.ok, true);
  // 100 * 8500 = 850000, C-001 gold tier = 5% = 42500
  assert.equal(r.value.subtotal, 850000);
  assert.equal(r.value.discount, 42500);
  assert.equal(r.value.total, 807500);
});

