    customerId: 'C-001',
    issueDate: '2026-01-01',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'DES-HOUR', qty: 2 },
    ],
  });
  assert.equal(r.ok, true);
